Print_Str_d     equ $F37A
Draw_VLp        equ $F410
Vec_Text_HW     equ $C82A
Vec_Buttons     equ $C811
Vec_0Ref_Enable equ $C824
Page            equ $C880
Cal             equ $C881

        org     $0000
        fcc     "g GCE 2026"
        fcb     $80
        fdb     $FD0D
        fcb     $F8,$50,$20,-$40
        fcc     "ZERO TEST"
        fcb     $80
        fcb     0

Start:
        clr     Page
Main:
        jsr     Wait_Recal
        clr     Vec_0Ref_Enable         ; (Draw_VLp: no re-zero of its own after the list)
        jsr     Read_Btns
        lda     Vec_Buttons
        bita    #1
        beq     Bt0
        ldb     #0
        stb     Page
Bt0
        bita    #2
        beq     Bt1
        ldb     #1
        stb     Page
Bt1
        lda     #$D0
        tfr     a,dp
        setdp   $D0
        lda     Page
        lbeq    Page1
        lbra    Page2

